-- ════════════════════════════════════════════════════════════════════════
-- PURULIA KASA — outlines of Jhalda and Raghunathpur towns and the 170 gram
-- panchayats (see 20260928050000_kasa_local_bodies.sql).
--
-- Towns: Survey of India village and town boundaries. Gram panchayats: Local
-- Government Directory (Ministry of Panchayati Raj). Both via india-geodata,
-- CC0, simplified to about 30 m. Generated by
-- `python3 tools/build-areas.py --local-bodies`; regenerate rather than edit.
-- Safe to re-run.
-- ════════════════════════════════════════════════════════════════════════

-- Generated by tools/build-areas.py. Do not edit by hand.
on conflict (id) do update set kind = excluded.kind, name = excluded.name, ward_no = excluded.ward_no,
  min_lat = excluded.min_lat, max_lat = excluded.max_lat, min_lng = excluded.min_lng, max_lng = excluded.max_lng,
  polygons = excluded.polygons, parent = excluded.parent;

-- Name the local body on every existing report.
update public.reports r set local_body = l ->> 'body', boundary_type = coalesce(l ->> 'body_type', r.boundary_type),
       area_kind = l ->> 'kind', block_name = l ->> 'block'
from (select id, kasa_private.locate(lat, lng, ward_no) l from public.reports) x
where x.id = r.id and x.l is not null
  and (r.local_body is distinct from x.l ->> 'body' or r.boundary_type is distinct from coalesce(x.l ->> 'body_type', r.boundary_type)
       or r.area_kind is distinct from x.l ->> 'kind' or r.block_name is distinct from x.l ->> 'block');
